mapper.select:
select id, token, user_id, status, order_no, created_at, expired_at, used_at
from xray_payment_submit_token
where token = #{token}

mapper.insert:
insert ignore into xray_payment_submit_token (
    token, user_id, status, order_no, created_at, expired_at, used_at
)
values (
    #{token}, #{userId}, #{status}, #{orderNo}, #{createdAt}, #{expiredAt}, #{usedAt}
)
